-- 056 - The client's own text (file "NEXTGEN SOCIO AND ENVIRO ADVISORS about.docx", message of 2026-11-14) on the four compliance pages that the Compliance menu opens, so every menu
--       entry lands on a heading with real words under it. The text is added to the top of the page body once (not again if the page already carries it); the page's existing
--       blocks stay below it. An administrator can edit all of it in Content & System > CMS > Pages.
SET NAMES utf8mb4;

UPDATE cms_pages
SET content_html = CONCAT('<h2>Wages, Working Hours &amp; Conditions of Employment</h2><p>NextGen supports organisations in developing transparent and legally compliant systems relating to wages, working hours, overtime, leave, attendance, payslips, wage records and employment conditions.</p><p>The objective is to promote fair and transparent wage administration while preventing wage-related disputes, discrimination and unfair labour practices. We assist organisations in reviewing their wage structures and employment practices against applicable statutory requirements and identifying areas requiring corrective action.</p><h2>Industrial Relations &amp; Grievance Redressal</h2><p>Healthy industrial relations are essential for sustainable organisational performance. NextGen assists management in establishing professional systems for employee communication, grievance handling, dispute prevention, disciplinary procedures, domestic enquiries and employer–employee relationship management.</p><p>We support the development of structured grievance-redressal mechanisms through which workers can raise concerns in a transparent, confidential and timely manner. Effective grievance management can help organisations identify workplace issues at an early stage and prevent them from developing into larger disputes.</p>', COALESCE(content_html, ''))
WHERE slug = 'payroll-compliance-ir' AND deleted_at IS NULL AND COALESCE(content_html, '') NOT LIKE '%Wages, Working Hours &amp; Conditions of Employment%';

UPDATE cms_pages
SET content_html = CONCAT('<h2>Social Security Compliance</h2><p>The Compliance Wing assists organisations in establishing effective systems for statutory social-security compliance, including applicable provisions relating to Employees’ Provident Fund, Employees’ State Insurance, gratuity, bonus, employee insurance, welfare benefits and other applicable statutory schemes.</p><p>Our services include compliance-gap identification, registration and contribution monitoring, statutory documentation, employee-benefit awareness and record-management support. Particular emphasis is placed on ensuring that eligible employees understand their statutory rights and that organisations maintain appropriate systems for timely implementation of applicable benefits.</p>', COALESCE(content_html, ''))
WHERE slug = 'social-security-compliance' AND deleted_at IS NULL AND COALESCE(content_html, '') NOT LIKE '%Social Security Compliance%';

UPDATE cms_pages
SET content_html = CONCAT('<h2>Industrial Safety &amp; Occupational Health</h2><p>NextGen provides professional assistance in establishing and strengthening industrial safety and occupational health management systems. This includes support for compliance with applicable occupational safety legislation, factory safety requirements, fire and life-safety provisions, electrical safety requirements, machinery safety, chemical safety and other workplace safety obligations.</p><p>Our safety services include Hazard Identification and Risk Assessment (HIRA), Job Safety Analysis (JSA), risk assessment, safety audits, workplace inspections, machine safety assessments, electrical safety assessments, chemical safety assessments, emergency preparedness, Permit-to-Work systems, PPE management, safety committees, accident investigation and corrective-action management.</p><p>We also support organisations in developing Emergency Response Plans (ERP), on-site emergency procedures, evacuation arrangements, emergency communication systems, mock-drill programmes and incident-response mechanisms. Safety awareness is strengthened through worker training, toolbox talks, induction programmes, supervisor training and continuous safety communication.</p><p>The ultimate objective is to develop a positive safety culture in which management and workers jointly participate in hazard prevention, safe working practices and continuous improvement.</p>', COALESCE(content_html, ''))
WHERE slug = 'health-safety-compliance' AND deleted_at IS NULL AND COALESCE(content_html, '') NOT LIKE '%Industrial Safety &amp; Occupational Health%';

UPDATE cms_pages
SET content_html = CONCAT('<h2>Environmental, Social &amp; Governance (ESG)</h2><p>NextGen assists organisations in developing and implementing ESG frameworks that integrate environmental performance, social responsibility and governance practices into organisational decision-making.</p><p>Our services may include ESG gap assessments, materiality-related support, environmental and social performance indicators, data collection systems, ESG documentation, reporting support and stakeholder communication.</p><p>The objective is to establish measurable systems through which organisations can understand and demonstrate their performance in areas such as environmental impact, employee welfare, occupational safety, resource consumption, waste management, ethical governance and social responsibility.</p><h2>Net Zero &amp; Climate Action</h2><p>NextGen supports organisations in understanding and managing their greenhouse-gas emissions through carbon-footprint assessment and climate-management programmes.</p><p>Our services may include assessment of Scope 1, Scope 2 and relevant Scope 3 emissions, identification of major emission sources, energy-efficiency opportunities, renewable-energy integration, emission-reduction strategies and development of practical Net Zero roadmaps.</p><p>The approach focuses first on measurement and reduction, followed by appropriate management of residual emissions in accordance with applicable frameworks and organisational objectives. We also support organisations in developing climate-resilience and resource-efficiency strategies.</p><h2>Environmental Compliance &amp; Governance</h2><p>The Environment Wing assists industries and organisations in meeting applicable environmental requirements under relevant environmental legislation, regulatory conditions, consent requirements and waste-management regulations.</p><p>Our services cover areas such as Water Act and Air Act compliance, Environmental Protection requirements, hazardous-waste management, solid-waste management, plastic-waste management, biomedical-waste management, wastewater management, ETP assessment, STP assessment, ZLD systems, environmental audits, water audits, waste audits, pollution-control systems and environmental documentation.</p><p>We also support organisations in improving resource efficiency through water conservation, wastewater recycling and reuse, energy efficiency, waste minimisation, material recovery and circular-economy approaches.</p><p>Particular attention is given to industries generating complex wastewater streams, including wastewater treatment systems involving ETP, RO, MEE and ZLD processes, where appropriate assessment of waste characteristics, salt generation, recovery possibilities, recycling opportunities and environmentally sound disposal methods can contribute to improved resource efficiency.</p>', COALESCE(content_html, ''))
WHERE slug = 'environmental-compliance' AND deleted_at IS NULL AND COALESCE(content_html, '') NOT LIKE '%Environmental, Social &amp; Governance (ESG)%';

